theme.css:
/* theme: Humming Current | The market hums with tension between record chip profits and the looming AI debt question, while politics churns beneath a deceptively calm surface. */
/* mood: tense */
/* layout: hero=centered; political-news=outline/grid-2; financial-news=stat/stack; entertainment-news=tile/grid-3; music-releases=plain/stack; stock-analysis=numbered/grid-2; outlook=timeline/stack */

.diary-page {
  --paper: #1a1508;
  --paper-alt: #2a2210;
  --ink: #f7f0d9;
  --ink-soft: #d8cdab;
  --muted: #a89a6f;
  --accent: #ffb347;
  --accent-ink: #1a1508;
  --rule: #4a3d1e;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;

  background: 
    linear-gradient(180deg, transparent 0%, transparent 60%, rgba(255, 179, 71, 0.04) 60%, rgba(255, 179, 71, 0.04) 62%, transparent 62%, transparent 100%),
    var(--paper);
}

.diary-page .diary-hero {
  background: 
    linear-gradient(135deg, var(--paper-alt) 0%, var(--paper) 50%, var(--paper-alt) 100%);
  border-bottom: 2px solid var(--accent);
}

.diary-page[data-hero="centered"] .diary-hero-inner {
  padding-block: 3rem 4rem;
}

.diary-page .diary-kicker {
  color: var(--accent);
  font-size: 0.8rem;
  letter-spacing: 0.3em;
  margin-top: 2rem;
}

.diary-page .diary-title {
  font-size: clamp(2.75rem, 7vw, 5.5rem);
  letter-spacing: 0.04em;
  line-height: 0.95;
  margin-top: 0.85rem;
  font-weight: 400;
  text-transform: uppercase;
}

.diary-page .diary-summary {
  font-size: clamp(1.15rem, 2vw, 1.35rem);
  font-style: italic;
  max-width: 42rem;
  margin-top: 1.25rem;
}

.diary-page .diary-theme-note {
  margin-top: 1.75rem;
  font-size: 0.9rem;
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 0.2rem 0.8rem;
  border-radius: 2px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.diary-page .diary-crumbs a {
  color: var(--muted);
  font-size: 0.8rem;
  letter-spacing: 0.08em;
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom-color: var(--rule);
}

.diary-page .diary-toc-label {
  letter-spacing: 0.2em;
  font-size: 0.7rem;
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
  font-size: 0.85rem;
  letter-spacing: 0.03em;
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-size: 0.7rem;
}

.diary-page .diary-toc-list {
  border-left-color: var(--rule);
}

.diary-page .diary-toc-link.is-active {
  border-left-color: var(--accent);
}

.diary-page .diary-section {
  padding-block: 3.5rem;
  border-top-color: var(--rule);
  position: relative;
}

.diary-page .diary-section:first-child {
  border-top: 0;
  padding-top: 2.5rem;
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-size: 0.75rem;
  letter-spacing: 0.2em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-size: clamp(2.2rem, 4vw, 3.2rem);
  letter-spacing: 0.03em;
  font-weight: 400;
  text-transform: uppercase;
}

.diary-page .diary-prose {
  font-size: 1.08rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-prose h3 {
  font-size: 0.78rem;
  letter-spacing: 0.2em;
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-size: 1.4rem;
  letter-spacing: 0.04em;
  font-weight: 400;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: currentColor;
  font-size: 0.65em;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose hr {
  border-top-color: var(--rule);
}

.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-card--outline .diary-card-inner {
  padding: 1.75rem;
  border: 1px solid var(--rule);
  border-radius: 0;
  position: relative;
  background: linear-gradient(135deg, rgba(255, 179, 71, 0.04) 0%, transparent 50%);
  transition: border-color 200ms ease;
}

.diary-page .diary-card--outline .diary-card-inner:hover {
  border-color: var(--accent);
}

.diary-page .diary-card--outline .diary-card-title {
  font-size: 1.5rem;
}

.diary-page .diary-card--tile .diary-card-inner {
  padding: 1.75rem;
  background: var(--paper-alt);
  border: 1px solid transparent;
  border-radius: 0;
  transition: border-color 200ms ease;
}

.diary-page .diary-card--tile .diary-card-inner:hover {
  border-color: var(--accent);
}

.diary-page .diary-card--tile .diary-card-title {
  font-size: 1.35rem;
}

.diary-page .diary-card--numbered .diary-card-inner {
  border-left: 3px solid var(--rule);
  padding-left: 1.5rem;
  margin-left: 0.5rem;
  position: relative;
  transition: border-color 200ms ease;
}

.diary-page .diary-card--numbered .diary-card-inner:hover {
  border-left-color: var(--accent);
}

.diary-page .diary-card--numbered .diary-card-index {
  font-size: 2.75rem;
  color: var(--accent);
  position: absolute;
  left: -0.6rem;
  top: 0;
  background: var(--paper);
  padding-inline: 0.2rem;
}

.diary-page .diary-card--numbered .diary-card-title {
  font-size: 1.3rem;
}

.diary-page .diary-card--stat .diary-card-inner {
  padding-top: 1.25rem;
  border-top: 3px solid var(--accent);
}

.diary-page .diary-card-figure {
  font-size: clamp(3rem, 10cqi, 4.5rem);
  color: var(--accent);
  text-shadow: 0 0 40px rgba(255, 179, 71, 0.2);
}

.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper), 0 0 12px rgba(255, 179, 71, 0.4);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  background: transparent;
  transition: background 200ms ease, color 200ms ease;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card-lede {
  border-left-color: var(--accent);
  font-size: 1.25rem;
  line-height: 1.5;
  color: var(--ink);
}

.diary-page .diary-markets-wrap {
  margin-bottom: 2.5rem;
}

.diary-page .diary-markets-label {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.diary-page .diary-spark {
  padding: 1rem 1.1rem 0.8rem;
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
}

.diary-page .diary-spark-label {
  font-size: 0.72rem;
  color: var(--muted);
}

.diary-page .diary-spark-value {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-spark-change {
  font-size: 0.72rem;
  font-weight: 600;
}

.diary-page .diary-spark.is-up {
  color: #8ba888;
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark-line polyline {
  stroke: currentColor;
}

.diary-page .diary-footer {
  border-top-color: var(--rule);
  font-size: 0.85rem;
}

.diary-page .diary-footer a {
  color: var(--ink);
  letter-spacing: 0.02em;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-prose a {
  white-space: normal !important;
}

.diary-page .diary-prose > * + * {
  margin-top: 1.1em;
}

.diary-page .diary-card-body {
  font-size: 1.06rem;
  line-height: 1.7;
}

@media (min-width: 1024px) {
  .diary-page .diary-body {
    gap: 4.5rem;
  }

  .diary-page .diary-toc {
    margin-top: 3.5rem;
  }

  .diary-page .diary-section {
    padding-block: 3.5rem;
  }
}

@media (max-width: 1023px) {
  .diary-page .diary-toc {
    margin-inline: -1.25rem;
    padding-inline: 1.25rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page .diary-card--outline .diary-card-inner,
  .diary-page .diary-card--tile .diary-card-inner,
  .diary-page .diary-card--numbered .diary-card-inner,
  .diary-page .diary-card-thread {
    transition: none;
  }
}
